<?php $page_title='Akses toko'; $this->load->view('staff/_layout_start',compact('user','page_title')); ?>
<div class="staff-hero"><div><span class="staff-kicker">HAK AKSES</span><h1>Pengelola toko</h1><p>Hubungkan akun pelaku UMKM ke toko yang dapat mereka kelola.</p></div></div><?php if($error): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?><?php if($this->input->get('tersimpan')): ?><div class="alert alert-success">Hak akses berhasil diperbarui.</div><?php endif; ?><section class="staff-panel catalog-panel"><h2>Berikan akses</h2><form method="post"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><input type="hidden" name="action" value="assign"><label>Akun pelaku UMKM<select name="user_id" class="form-select" required><option value="">Pilih akun</option><?php foreach($users as $account): ?><option value="<?= (int)$account['id'] ?>"><?= html_escape($account['full_name'].' — '.$account['email']) ?></option><?php endforeach; ?></select></label><label>Toko<select name="store_id" class="form-select" required><option value="">Pilih toko</option><?php foreach($stores as $store): ?><option value="<?= (int)$store['id'] ?>"><?= html_escape($store['display_name']) ?></option><?php endforeach; ?></select></label><button class="btn btn-primary" type="submit">Berikan akses</button></form></section><section class="staff-panel catalog-panel"><h2>Akses terdaftar</h2><form class="staff-list-filter" method="get" action="<?= site_url('pengelola/akses-toko') ?>"><label>Cari akun atau toko<input type="search" name="q" value="<?= html_escape($search) ?>" maxlength="80" placeholder="Nama akun atau toko"></label><label>Status<select name="status"><option value="">Semua</option><option value="active" <?= $status==='active'?'selected':'' ?>>Aktif</option><option value="revoked" <?= $status==='revoked'?'selected':'' ?>>Dicabut</option></select></label><?php $this->load->view('staff/_list_size',array('per_page'=>$per_page)); ?><button type="submit">Terapkan</button><a href="<?= site_url('pengelola/akses-toko') ?>">Reset</a></form><p class="staff-list-count"><?= number_format($total,0,',','.') ?> akses</p><div class="catalog-list"><?php foreach($assignments as $item): ?><div class="catalog-access-row"><div><strong><?= html_escape($item['display_name']) ?></strong><small><?= html_escape($item['full_name']) ?> · <?= $item['status']==='active'?'Aktif':'Dicabut' ?></small></div><?php if($item['status']==='active'): ?><form method="post"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><input type="hidden" name="action" value="revoke"><input type="hidden" name="store_id" value="<?= (int)$item['store_id'] ?>"><input type="hidden" name="user_id" value="<?= (int)$item['user_id'] ?>"><button class="btn btn-outline-danger" type="submit" onclick="return confirm('Cabut akses ini?')">Cabut</button></form><?php endif; ?></div><?php endforeach; ?></div><?php $this->load->view('staff/_pagination',array('base'=>site_url('pengelola/akses-toko'),'params'=>array('q'=>$search,'status'=>$status,'per_page'=>$per_page),'page'=>$page,'pages'=>$pages)); ?></section>
<?php $this->load->view('staff/_layout_end'); ?>
